Ejecución del agente finalizada.

CONSULTA DEL CLIENTE
{{ $('Recibir consulta del cliente').item.json.chatInput }}

RESPUESTA DEL AGENTE
{{ $json.output }}

CONSULTAS A HERRAMIENTAS
{{ ($json.intermediateSteps || []).map((paso, indice) => {
  const registros = typeof paso.observation === 'string'
    ? JSON.parse(paso.observation)
    : paso.observation;

  const productos = registros.map(registro => {
    const producto = registro.fields;
    return '• ' + producto.PRODUCTO
      + ' | Precio: ' + producto.PRECIO + ' ' + producto.MONEDA
      + ' | Stock: ' + producto.STOCK;
  }).join('\n');

  return 'Consulta ' + (indice + 1)
    + '\nHerramienta: ' + paso.action.tool
    + '\nDatos consultados:\n' + productos;
}).join('\n\n') || 'El agente no necesitó consultar herramientas.' }}
